/** 按 60Hz 取样的数组在时刻 [t]（秒）的值，线性插值，超出两端取端点 */
internal fun FloatArray.at(t: Float): Float {
    val i = maxOf(0f, t * 60f)
    val j = minOf(size - 1, i.toInt())
    if (j >= size - 1) return this[size - 1]
    val f = i - j
    return this[j] + (this[j + 1] - this[j]) * f
}
